window.AUTH=window.AUTH||{};window.AUTH["86-1471"]={"d":"86-1471","id":"1987/86-1471","n":"Lyng v. International Union, United Automobile, Aerospace & Agricultural Implement Workers of America","src":["osg"],"briefs":[{"k":"petitioner","label":"Brief for the appellant","date":"","url":"https://www.justice.gov/osg/media/204771/dl?inline","side":"pet","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/richard-lyng-secretary-agriculture-appellant-v-international-union-united-automobile","toa":false,"n":45}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep485/usrep485360/usrep485360.pdf","tr":false,"items":[{"t":"case","label":"Heckler v. Turner","cite":"470 U.S. 184","y":1985,"id":"1984/83-1097","sc":1,"sum":"In calculating a family's need for AFDC benefits, the responsible state agency must treat mandatory tax withholdings as a work expense encompassed within the flat-sum disregard of §402(a)(8)(A)(ii), rather than as a separate deduction in determining \"income\" under §402(a)(7) (A).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Abood v. Detroit Bd. of Education","cite":"431 U.S. 209","y":1977,"id":"1976/75-1153","sc":1,"op":4,"sum":"A Michigan statute authorizing union representation of local governmental employees permits an \"agency shop\" arrangement, whereby every employee represented by a union, even though not a union member, must pay to the union, as a condition of employment, a service charge equal in amount to union dues. Appellant teachers filed actions (later consolidated) m Michigan state court against appellee Detroit Board of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Sherbert v. Verner","cite":"374 U.S. 398","y":1963,"id":"1962/526","sc":1,"op":2,"sum":"The Court found that the denial of unemployment compensation because of religious practices violated the First and Fourteenth Amendments.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Walters v. Nat'l Ass'n of Radiation Survivors","cite":"473 U.S. 305","y":1985,"id":"1984/84-571","sc":1,"sum":"Title 38 U. S. C. § 3404(c) limits to $10 the fee that may be paid an attorney or agent who represents a veteran seeking benefits from the Veterans' Administration (VA) for service-connected death or disability. Appellees (two veterans' organizations, three individual veterans, and a veteran's widow) brought an action in Federal District Court claiming that the fee limitation denied them any realistic opportunity to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"City of Cleburne v. Cleburne Living Center, Inc.","cite":"473 U.S. 432","y":1985,"id":"1984/84-468","sc":1,"op":6,"sum":"In a unanimous judgment, the Court held that the denial of the special use permit to Cleburne Living Centers, Inc. was premised on an irrational prejudice against the mentally retarded, and hence unconstitutional under the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Plyler v. Doe","cite":"457 U.S. 202","y":1982,"id":"1981/80-1538","sc":1,"op":2,"sum":"The Court found that it was unconstitutional for the State to withhold funds from school districts educating children of illegal aliens.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Schweiker v. Wilson","cite":"450 U.S. 221","y":1981,"id":"1980/79-1380","sc":1,"sum":"Appellees' rights to equal protection were not violated by denying them SSI benefits.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Califano v. Boles","cite":"443 U.S. 282","y":1979,"id":"1978/78-808","sc":1,"sum":"Section 202 (g) (1) of the Social Security Act restricting \"mother's insurance benefits\" to widows and divorced wives of wage earners does not violate the equal protection component of the Due Process Clause of the Fifth Amendment by thus denying such benefits to the mother of an illegitimate child because she was never married to the wage earner who fathered the child.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Ohio Bureau of Employment Services v. Hodory","cite":"431 U.S. 471","y":1977,"id":"1976/75-1707","sc":1,"op":6,"sum":"Appellee, an employee of United States Steel Corporation (USS) at a plant in Ohio, was furloughed when the plant was shut down because of a reduction in fuel supply resulting from a nationwide strike of workers at USS's coal mines. Appellee applied to appellant Ohio Bureau of Employment Services for unemployment benefits but his claim was disallowed under an Ohio statute that disqualified a worker from such benefits …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Super Tire Engineering Co. v. McCorkle","cite":"416 U.S. 115","y":1974,"id":"1973/72-1554","sc":1,"sum":"To the extent that declaratoryrelief was sought, the case-or-controversy requirement of Art. III, § 2, and the Declaratory Judgment Act is completely satisfied. -","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States Railroad Retirement Bd. v. Fritz","cite":"449 U.S. 166","y":1980,"id":"1980/79-870","sc":1,"op":1,"sum":"The Court held that laws may create classifications that are not elegant or “artfully drawn” but that are not unconstitutional. The Constitution would allow Congress to deny windfall benefits to all employees, therefore it was not unconstitutional to deny them to some.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Weinberger v. Salfi","cite":"422 U.S. 749","y":1975,"id":"1974/74-214","sc":1,"sum":"After her husband of less than six months died, appellee widow filed applications for mother's Social Security insurance benefits for herself and child's insurance benefits for her daughter by a previous marriage, but the Social Security Administration (SSA), both initially and on reconsideration at the regional level, denied the applications on the basis of the duration-of-relationship requirements of the Social …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Vance v. Bradley","cite":"440 U.S. 93","y":1979,"id":"1978/77-1254","sc":1,"sum":"The Court emphasized the distinction between the Civil Service and Foreign Service, and the \"special attention\" paid to the Foreign Service by Congress.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Flemming v. Nestor","cite":"363 U.S. 603","y":1960,"id":"1959/54","sc":1,"sum":"The Court held that the Social Security system was meant to be a form of long-term social insurance that has to constantly adapt to the demands of a changing workforce, which prevents it from fitting within the framework of the right to accrued property.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"United Steelworkers v. Block","cite":"578 F. Supp. 1417","y":1982,"court":"D.S.D.","url":"https://www.courtlistener.com/c/F.%20Supp./578/1417/","by":{"0":""}},{"t":"case","label":"Florida AFL-CIO v. Florida Dep't of Labor & Employment Security","cite":"676 F.2d 513","y":1982,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/676/513/","sum":"Rejecting First Amendment challenge to state statute that withheld unemployment compensation from workers who quit their jobs upon expiration of labor contracts.","sumSrc":"brief:0","by":{"0":""}},{"t":"case","label":"Harris v. McRae","cite":"448 U.S. 297","y":1980,"id":"1979/79-1268","sc":1,"op":2,"sum":"The Court held that states participating in the Medicaid program were not obligated to fund medically necessary abortions under Title XIX.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Norwood v. Harrison","cite":"413 U.S. 455","y":1973,"id":"1972/72-77","sc":1,"op":1,"sum":"A three-judge District Court sustained the validity of a Mississippi statutory program, begun in 1940, under which textbooks are purchased by the State and lent to students in both public and private schools, without reference to whether any participating private school has racially discriminatory policies. The number of private secular schools in Mississippi, with a virtually all-white student population, has …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Regan v. Taxation With Representation of Washington","cite":"461 U.S. 540","y":1983,"id":"1982/81-2338","sc":1,"op":2,"sum":"No and no. Justice William H. Rehnquist authored the opinion for a unanimous court. Allowing a non-profit to solicit tax-deductible donations is a form of paying for its operations.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Maher v. Roe","cite":"432 U.S. 464","y":1977,"id":"1976/75-1440","sc":1,"op":1,"sum":"In a 6-to-3 decision, the Court held that the Connecticut law placed no obstacles in the pregnant woman's path to an abortion, and that it did not \"impinge upon the fundamental right recognized in Roe.\" The Court noted that there was a distinction between direct state interference with a protected activity and \"state encouragement of alternative activity consonant with legislative policy.\" Holding that financial need alone did not identify a suspect class under the Equal Protection Clause, the Court found that the law was \"rationally related\" to a legitimate state interest and survived scrutiny under the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Cammarano v. United States","cite":"358 U.S. 498","y":1959,"id":"1958/29","sc":1,"sum":"1. In computing federal income taxes, sums paid by a taxpayer to an organization which expended 'them in extensive publicity programs designed to persuade voters to cast their ballots against proposed state initiative legislation which -would have seriously affected or wholly destroyed the taxpayer's business may not be deducted from gross income as \"ordinary and necessary\" business expenses under § 23 (a) (1) (A) …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"American Ship Building Co. v. NLRB","cite":"380 U.S. 300","y":1965,"id":"1964/255","sc":1,"sum":"An employer does not commit an unfair labor practice under either § 8 (a) (1) or § 8 (a) (3) of the Act when, after an impasse has been reached in negotiations, he temporarily shuts down his plant and lays off his employees for the sole purpose of applying economic pressure in support of his legitimate bargaining position. Pp. 308-318. 118 U. S. App. D. C. 78, 331 F. 2d 839, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Thomas v. Review Board","cite":"450 U.S. 707","y":1981,"id":"1980/79-952","sc":1,"sum":"The Court held that the Review Board's denial of unemployment benefits to Thomas violated his First Amendment right to the free exercise of religion.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Accord, Russo v. Kirby","cite":"453 F.2d 548","y":1971,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/453/548/","sum":"Rejecting First Amendment and equal protection challenges to state law denying welfare benefits to strikers.","sumSrc":"brief:0","by":{"0":""}},{"t":"case","label":"Francis v. Davidson","cite":"340 F. Supp. 351","url":"https://www.courtlistener.com/c/F.%20Supp./340/351/","by":{"0":""}},{"t":"case","label":"Jones v. Helms","cite":"452 U.S. 412","y":1981,"id":"1980/80-850","sc":1,"sum":"Under a Georgia statute, a parent who willfully and voluntarily abandons his or her dependent child is guilty of a misdemeanor, and those parents who commit that offense within Georgia and thereafter leave the State are guilty of a felony. Appellee pleaded guilty in a Georgia state court to the felony of abandoning his child and leaving the State, thereby formally admitting that he had willfully and voluntarily …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"San Antonio Independent School District v. Rodriguez","cite":"411 U.S. 1","y":1973,"id":"1972/71-1332","sc":1,"sum":"The Court found that inequalities in the finance system of Texas public schools did not violate the Fourteenth Amendment's Equal Protection Clause.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Clements v. Fashing","cite":"457 U.S. 957","y":1982,"id":"1981/80-1290","sc":1,"sum":"The judgment is reversed. 631 F. 2d 731, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United Steelworkers v. Bouligny, Inc.","cite":"382 U.S. 145","y":1965,"id":"1965/19","sc":1,"sum":"Respondent, a North Carolina corporation, brought this defamation action in a North Carolina court against petitioner, an unincorporated labor union. Petitioner's principal place of business purportedly is Pennsylvania, where for purposes of diversity jurisdiction it claimed citizenship, though some of its members reside in North Carolina. Petitioner removed the case to a Federal District Court, which refused to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Mathews v. De Castro","cite":"429 U.S. 181","y":1976,"id":"1976/75-1197","sc":1,"op":1,"sum":"The statutory classification of § 202 (b) (1) of the Social Security Act whereby a married woman under 62 whose husband retires or becomes disabled is granted monthly benefits under the Act if she has a minor or other dependent child in her care, but a divorced woman under 62 whose ex-husband retires or becomes disabled does not receive such benefits, held not to violate the Due Process Clause of the Fifth …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Helvering v. Davis","cite":"301 U.S. 619","y":1937,"id":"scdb/1936-103","sc":1,"sum":"(1) Title II being valid, there is no occasion to inquire whether Title VIII must fall if Title II were void. P. 645. (2) The tax upon employers is a valid excise or duty upon the relation of employment. Steward Machine Co. v. Davis, ante p. 548. P. 645. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Schweiker v. Hogan","cite":"457 U.S. 569","y":1982,"id":"1981/81-213","sc":1,"sum":"Section 1903(f) of the Social Security Act provides that federal reimbursement to States electing to provide Medicaid benefits to the \"medically needy\" is available only if the income of those persons, after deduction of incurred medical expenses, is less than 133 14% of the state Aid to Families With Dependent Children (AFDC) payment level. Section 1903(f) specifically excepts from this rule the \"categorically …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Califano v. Aznavorian","cite":"439 U.S. 170","y":1978,"id":"1978/77-991","sc":1,"sum":"Section 1611 (f) of the Social Security Act, which provides that no benefits under the Supplemental Security Income (SSI) program for the needy aged, blind, and disabled are to be paid for any month that the recipient spends entirely outside of the United States, held to be constitutional as having a rational basis and not to impose an impermissible burden on the freedom of international travel in violation of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Mathews v. Lucas","cite":"427 U.S. 495","y":1976,"id":"1975/75-88","sc":1,"op":1,"sum":"The Social Security Act provides that a child of an individual who died fully insured under the Act, is entitled to surviving child's benefits if the child is under 18, or a student under 22, and was dependent at the time of the parent's death. A child is considered dependent if the insured parent was living with him or contributed to the child's support at the time of death. Certain children, however, need not …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Accord, New York Tel. Co. v. New York Labor Dep't","cite":"440 U.S. 519","y":1979,"id":"1978/77-961","sc":1,"sum":"The judgment is affirmed. Pp. 527-546; 546-547; 547-551. 566 F. 2d 388, affirmed. MR. JUSTICE STEVENS, joined by MR. JUSTICE WHITE and MR. JUSTICE REHNQUIST, concluded that Congress, in enacting the NLRA and SSA, did not intend to pre-empt a State's power to pay unemployment compensation to strikers.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Dandridge v. Williams","cite":"397 U.S. 471","y":1970,"id":"1969/131","sc":1,"op":1,"sum":"The Court concluded that the Maryland provision violated neither the Social Security Act nor the Equal Protection Clause.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Massachusetts Bd. of Retirement v. Murgia","cite":"427 U.S. 307","y":1976,"id":"1975/74-1044","sc":1,"op":1,"sum":"The Court held that the law did not violate the Equal Protection Clause. The Court found that the right of governmental employment was not per se fundamental, and that uniformed state police officers over 50 did not constitute a suspect class under the Clause.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Frontiero v. Richardson","cite":"411 U.S. 677","y":1973,"id":"1972/71-1694","sc":1,"sum":"A case striking down two federal statutes that imposed burdens on female service members but not male service members seeking benefits for their spouses.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Johnson v. Robison","cite":"415 U.S. 361","id":"1973/72-1297","sc":1,"sum":"Appellee, who had been exempted from military service as a Class 1-0 conscientious objector bo. who perfurmed required alternative civilian service, after being denied educational benefits under the Veterans' Readjustmcnt Benefits Act of 1966 brought this class action for a declaratory judgment that' the provisions of the Act making him and his class ineligible for such benefits violated the First Amendment's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/28/1252","op":1,"tname":"Judiciary and Judicial Procedure","by":{"0":""}},{"t":"usc","label":"7 U.S.C. § 2015","url":"https://www.law.cornell.edu/uscode/text/7/2015","subs":["(d)(3)"],"stext":{"head":"§2015. Eligibility disqualifications","paras":[[0,"(a) Additional specific conditions rendering individuals ineligible"],[0,"In addition to meeting the standards of eligibility prescribed in section 2014 of this title, households and individuals who are members of eligible households must also meet and comply with the specific requirements of this section to be eligible for participation in the supplemental nutrition assistance program."],[0,"(b) Fraud and misrepresentation; disqualification penalties; ineligibility period; applicable procedures"],[0,"(1) Any person who has been found by any State or Federal court or administrative agency to have intentionally (A) made a false or misleading statement, or misrepresented, concealed or withheld facts, or (B) committed any act that constitutes a violation of this chapter, the regulations issued thereunder, or any State statute, for the purpose of using, presenting, transferring, acquiring, receiving, or possessing program benefits shall, immediately upon the rendering of such determination, become ineligible for further participation in the program—"],[1,"(i) for a period of 1 year upon the first occasion of any such determination;"],[1,"(ii) for a period of 2 years upon—"],[2,"(I) the second occasion of any such determination; or"],[2,"(II) the first occasion of a finding by a Federal, State, or local court of the trading of a controlled substance (as defined in section 802 of title 21) for benefits; and"],[1,"(iii) permanently upon—"],[2,"(I) the third occasion of any such determination;"],[2,"(II) the second occasion of a finding by a Federal, State, or local court of the trading of a controlled substance (as defined in section 802 of title 21) for benefits;"],[2,"(III) the first occasion of a finding by a Federal, State, or local court of the trading of firearms, ammunition, or explosives for benefits; or"],[2,"(IV) a conviction of an offense under subsection (b) or (c) of section 2024 of this title involving an item covered by subsection (b) or (c) of section 2024 of this title having a value of $500 or more."],[0,"During the period of such ineligibility, no household shall receive increased benefits under this chapter as the result of a member of such household having been disqualified under this subsection."],[0,"(2) Each State agency shall proceed against an individual alleged to have engaged in such activity either by way of administrative hearings, after notice and an opportunity for a hearing at the State level, or by referring such matters to appropriate authorities for civil or criminal action in a court of law."],[0,"(3) Such periods of ineligibility as are provided for in paragraph (1) of this subsection shall remain in effect, without possibility of administrative stay, unless and until the finding upon which the ineligibility is based is subsequently reversed by a court of appropriate jurisdiction, but in no event shall the period of ineligibility be subject to review."],[0,"(4) The Secretary shall prescribe such regulations as the Secretary may deem appropriate to ensure that information concerning any such determination with respect to a specific individual is forwarded to the Office of the Secretary by any appropriate State or Federal entity for the use of the Secretary in administering the provisions of this section. No State shall withhold such information from the Secretary or the Secretary's designee for any reason whatsoever."],[0,"(c) Refusal to provide necessary information"],[0,"Except in a case in which a household is receiving transitional benefits during the transitional benefits period under section 2020(s) of this title, no household shall be eligible to participate in the supplemental nutrition assistance program if it refuses to cooperate in providing information to the State agency that is necessary for making a determination of its eligibility or for completing any subsequent review of its eligibility."],[1,"(1)(A) A State agency may require certain categories of households to file periodic reports of income and household circumstances in accordance with standards prescribed by the Secretary, except that a State agency may not require periodic reporting—"],[2,"(i) for periods shorter than 4 months by migrant or seasonal farmworker households;"],[2,"(ii) for periods shorter than 4 months by households in which all members are homeless individuals; or"],[2,"(iii) for periods shorter than 1 year by households that have no earned income and in which all adult members are elderly or disabled."],[1,"(B) Each household that is not required to file such periodic reports shall be required to report or cause to be reported to the State agency changes in income or household circumstances that the Secretary considers necessary to assure accurate eligibility and benefit determinations."],[1,"(C) A State agency may require periodic reporting on a monthly basis by households residing on a reservation only if—"],[2,"(i) the State agency reinstates benefits, without requiring a new application, for any household residing on a reservation that submits a report not later than 1 month after the end of the month in which benefits would otherwise be provided;"],[2,"(ii) the State agency does not delay, reduce, suspend, or terminate the allotment of a household that submits a report not later than 1 month after the end of the month in which the report is due;"],[2,"(iii) on March 25, 1994, the State agency requires households residing on a reservation to file periodic reports on a monthly basis; and"],[2,"(iv) the certification period for households residing on a reservation that are required to file periodic reports on a monthly basis is 2 years, unless the State demonstrates just cause to the Secretary for a shorter certification period."],[1,"(D) Frequency of reporting.—"],[2,"(i) In general.—Except as provided in subparagraphs (A) and (C), a State agency may require households that report on a periodic basis to submit reports—"],[3,"(I) not less often than once each 6 months; but"],[3,"(II) not more often than once each month."],[2,"(ii) Reporting by households with excess income.—A household required to report less often than once each 3 months shall, notwithstanding subparagraph (B), report in a manner prescribed by the Secretary if the income of the household for any month exceeds the income standard of eligibility established under section 2014(c)(2) of this title."],[1,"(2) Any household required to file a periodic report under paragraph (1) of this subsection shall, (A) if it is eligible to participate and has filed a timely and complete report, receive its allotment, based on the reported information for a given month, within thirty days of the end of that month unless the Secretary determines that a longer period of time is necessary, (B) have available special procedures that permit the filing of the required information in the event all adult members of the household are mentally or physically handicapped or lacking in reading or writing skills to such a degree as to be unable to fill out the required forms, (C) have a reasonable period of time after the close of the month in which to file their reports on State agency designed forms, (D) be afforded prompt notice of failure to file any report timely or completely, and given a reasonable opportunity to cure that failure (with any applicable time requirements extended accordingly) and to exercise its rights under section 2020(e)(10) of this title, and (E) be provided each month (or other applicable period) with an appropriate, simple form for making the required reports of the household together with clear instructions explaining how to complete the form and the rights and responsibilities of the household under any periodic reporting system."],[1,"(3) Reports required to be filed under paragraph (1) of this subsection shall be considered complete if they contain the information relevant to eligibility and benefit determinations that is specified by the State agency. All report forms, including those related to periodic reports of circumstances, shall contain a description, in understandable terms in prominent and bold face lettering, of the appropriate civil and criminal provisions dealing with violations of this chapter including the prescribed penalties. Reports required to be filed monthly under paragraph (1) shall be the sole reporting requirement for subject matter included in such reports. In promulgating regulations implementing these reporting requirements, the Secretary shall consult with the Commissioner of Social Security and the Secretary of Health and Human Services, and, wherever feasible, households that receive assistance under title IV–A of the Social Security Act [42 U.S.C. 601 et seq.] and that are required to file comparable reports under that Act [42 U.S.C. 301 et seq.] shall be provided the opportunity to file reports at the same time for purposes of this chapter and the Social Security Act."],[1,"(4) Except as provided in paragraph (1)(C), any household that fails to submit periodic reports required by paragraph (1) shall not receive an allotment for the payment period to which the unsubmitted report applies until such report is submitted."],[1,"(5) The Secretary is authorized, upon the request of a State agency, to waive any provisions of this subsection (except the provisions of the first sentence of paragraph (1) which relate to households which are not required to file periodic reports) to the extent necessary to permit the State agency to establish periodic reporting requirements for purposes of this chapter which are similar to the periodic reporting requirements established under the State program funded under part A of title IV of the Social Security Act (42 U.S.C. 601 et seq.) in that State."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/7/2015?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§2015. Eligibility disqualifications","tname":"Agriculture","by":{"0":""}},{"t":"usc","label":"7 U.S.C. § 2011","url":"https://www.law.cornell.edu/uscode/text/7/2011","stext":{"head":"§2011. Congressional declaration of policy","paras":[[0,"It is declared to be the policy of Congress, in order to promote the general welfare, to safeguard the health and well-being of the Nation's population by raising levels of nutrition among low-income households. Congress finds that the limited food purchasing power of low-income households contributes to hunger and malnutrition among members of such households. Congress further finds that increased utilization of food in establishing and maintaining adequate national levels of nutrition will promote the distribution in a beneficial manner of the Nation's agricultural abundance and will strengthen the Nation's agricultural economy, as well as result in more orderly marketing and distribution of foods. To alleviate such hunger and malnutrition, a supplemental nutrition assistance program is herein authorized which will permit low-income households to obtain a more nutritious diet through normal channels of trade by increasing food purchasing power for all eligible households who apply for participation."],[0,"That program includes as a purpose to assist low-income adults in obtaining employment and increasing their earnings. Such employment and earnings, along with program benefits, will permit low-income households to obtain a more nutritious diet through normal channels of trade by increasing food purchasing power for all eligible households who apply for participation."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/7/2011?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2011. Congressional declaration of policy","tname":"Agriculture","by":{"0":""}},{"t":"usc","label":"7 U.S.C. § 2012","url":"https://www.law.cornell.edu/uscode/text/7/2012","subs":["(i)"],"stext":{"head":"§2012. Definitions","paras":[[0,"As used in this chapter, the term:"],[0,"(a) \"Access device\" means any card, plate, code, account number, or other means of access, including point of sale devices, that can be used, alone or in conjunction with another access device, to obtain payments, allotments, benefits, money, goods, or other things of value, or that can be used to initiate a transfer of funds under this chapter."],[0,"(b) \"Allotment\" means the total value of benefits a household is authorized to receive during each month."],[0,"(c) \"Allowable medical expenses\" means expenditures for (1) medical and dental care, (2) hospitalization or nursing care (including hospitalization or nursing care of an individual who was a household member immediately prior to entering a hospital or nursing home), (3) prescription drugs when prescribed by a licensed practitioner authorized under State law and over-the-counter medication (including insulin) when approved by a licensed practitioner or other qualified health professional, (4) health and hospitalization insurance policies (excluding the costs of health and accident or income maintenance policies), (5) medicare premiums related to coverage under title XVIII of the Social Security Act [42 U.S.C. 1395 et seq.], (6) dentures, hearing aids, and prosthetics (including the costs of securing and maintaining a seeing eye dog), (7) eye glasses prescribed by a physician skilled in eye disease or by an optometrist, (8) reasonable costs of transportation necessary to secure medical treatment or services, and (9) maintaining an attendant, homemaker, home health aide, housekeeper, or child care services due to age, infirmity, or illness."],[0,"(d) Benefit.—The term \"benefit\" means the value of supplemental nutrition assistance provided to a household by means of—"],[1,"(1) an electronic benefit transfer under section 2016(h) of this title; or"],[1,"(2) other means of providing assistance, as determined by the Secretary."],[0,"(e) Benefit Issuer.—The term \"benefit issuer\" means any office of the State agency or any person, partnership, corporation, organization, political subdivision, or other entity with which a State agency has contracted for, or to which it has delegated functional responsibility in connection with, the issuance of benefits to households."],[0,"(f) \"Certification period\" means the period for which households shall be eligible to receive benefits. The certification period shall not exceed 12 months, except that the certification period may be up to 24 months if all adult household members are elderly or disabled. A State agency shall have at least 1 contact with each certified household every 12 months. The limits specified in this subsection may be extended until the end of any transitional benefit period established under section 2020(s) of this title."],[0,"(g) \"Coupon\" means any coupon, stamp, type of certificate, authorization card, cash or check issued in lieu of a coupon."],[0,"(h) \"Drug addiction or alcoholic treatment and rehabilitation program\" means any such program conducted by a private nonprofit organization or institution, or a publicly operated community mental health center, under part B of title XIX of the Public Health Service Act (42 U.S.C. 300x et seq.) to provide treatment that can lead to the rehabilitation of drug addicts or alcoholics."],[0,"(i) EBT Card.—The term \"EBT card\" means an electronic benefit transfer card issued under section 2016(h) of this title."],[0,"(j) \"Elderly or disabled member\" means a member of a household who—"],[1,"(1) is sixty years of age or older;"],[1,"(2)(A) receives supplemental security income benefits under title XVI of the Social Security Act (42 U.S.C. 1381 et seq.), or Federally or State administered supplemental benefits of the type described in section 212(a) of Public Law 93–66 (42 U.S.C. 1382 note), or"],[1,"(B) receives Federally or State administered supplemental assistance of the type described in section 1616(a) of the Social Security Act (42 U.S.C. 1382e(a)), interim assistance pending receipt of supplemental security income, disability-related medical assistance under title XIX of the Social Security Act (42 U.S.C. 1396 et seq.), or disability-based State general assistance benefits, if the Secretary determines that such benefits are conditioned on meeting disability or blindness criteria at least as stringent as those used under title XVI of the Social Security Act;"],[1,"(3) receives disability or blindness payments under title I, II, X, XIV, or XVI of the Social Security Act [42 U.S.C. 301 et seq., 401 et seq., 1201 et seq., 1351 et seq., 1381 et seq.] or receives disability retirement benefits from a governmental agency because of a disability considered permanent under section 221(i) of the Social Security Act (42 U.S.C. 421(i));"],[1,"(4) is a veteran who—"],[2,"(A) has a service-connected or non-service-connected disability which is rated as total under title 38; or"],[2,"(B) is considered in need of regular aid and attendance or permanently housebound under such title;"],[1,"(5) is a surviving spouse of a veteran and—"],[2,"(A) is considered in need of regular aid and attendance or permanently housebound under title 38; or"],[2,"(B) is entitled to compensation for a service-connected death or pension benefits for a non-service-connected death under title 38, and has a disability considered permanent under section 221(i) of the Social Security Act (42 U.S.C. 421(i));"],[1,"(6) is a child of a veteran and—"],[2,"(A) is considered permanently incapable of self-support under section 1314 of title 38; or"],[2,"(B) is entitled to compensation for a service-connected death or pension benefits for a non-service-connected death under title 38, and has a disability considered permanent under section 221(i) of the Social Security Act (42 U.S.C. 421(i)); or"],[1,"(7) is an individual receiving an annuity under section 2(a)(1)(iv) or 2(a)(1)(v) of the Railroad Retirement Act of 1974 (45 U.S.C. 231a(a)(1)(iv) or 231a(a)(1)(v)), if the individual's service as an employee under the Railroad Retirement Act of 1974 [45 U.S.C. 231 et seq.], after December 31, 1936, had been included in the term \"employment\" as defined in the Social Security Act [42 U.S.C. 301 et seq.], and if an application for disability benefits had been filed."],[0,"(k) \"Food\" means (1) any food or food product for home consumption except alcoholic beverages, tobacco, hot foods or hot food products ready for immediate consumption other than those authorized pursuant to clauses (3), (4), (5), (7), (8), and (9) of this subsection, and any deposit fee in excess of the amount of the State fee reimbursement (if any) required to purchase any food or food product contained in a returnable bottle or can, regardless of whether the fee is included in the shelf price posted for the food or food product, (2) seeds and plants for use in gardens to produce food for the personal consumption of the eligible household, (3) in the case of those persons who are sixty years of age or over or who receive supplemental security income benefits or disability or blindness payments under title I, II, X, XIV, or XVI of the Social Security Act [42 U.S.C. 301 et seq., 401 et seq., 1201 et seq., 1351 et seq., 1381 et seq.], and their spouses, meals prepared by and served in senior citizens' centers, apartment buildings occupied primarily by such persons, public or private nonprofit establishments (eating or otherwise) that feed such persons, private establishments that contract with the appropriate agency of the State to offer meals for such persons at concessional prices subject to section 2018(h) of this title, and meals prepared for and served to residents of federally subsidized housing for the elderly, (4) in the case of persons sixty years of age or over and persons who are physically or mentally handicapped or otherwise so disabled that they are unable adequately to prepare all of their meals, meals prepared for and delivered to them (and their spouses) at their home by a public or private nonprofit organization or by a private establishment that contracts with the appropriate State agency to perform such services at concessional prices subject to section 2018(h) of this title, (5) in the case of narcotics addicts or alcoholics, and their children, served by drug addiction or alcoholic treatment and rehabilitation programs, meals prepared and served under such programs, (6) in the case of certain eligible households living in Alaska, equipment for procuring food by hunting and fishing, such as nets, hooks, rods, harpoons, and knives (but not equipment for purposes of transportation, clothing, or shelter, and not firearms, ammunition, and explosives) if the Secretary determines that such households are located in an area of the State where it is extremely difficult to reach stores selling food and that such households depend to a substantial extent upon hunting and fishing for subsistence, (7) in the case of disabled or blind recipients of benefits under title I, II, X, XIV, or XVI of the Social Security Act [42 U.S.C. 301 et seq., 401 et seq., 1201 et seq., 1351 et seq., 1381 et seq.], and individuals described in paragraphs (2) through (7) of subsection (j), who are residents in a public or private nonprofit group living arrangement that serves no more than sixteen residents and is certified by the appropriate State agency or agencies under regulations issued under section 1616(e) of the Social Security Act [42 U.S.C. 1382e(e)] or under standards determined by the Secretary to be comparable to standards implemented by appropriate State agencies under such section, meals prepared and served under such arrangement, (8) in the case of women and children temporarily residing in public or private nonprofit shelters for battered women and children, meals prepared and served, by such shelters, and (9) in the case of households that do not reside in permanent dwellings and households that have no fixed mailing addresses, meals prepared for and served by a public or private nonprofit establishment (approved by an appropriate State or local agency) that feeds such individuals and by private establishments that contract with the appropriate agency of the State to offer meals for such individuals at concessional prices subject to section 2018(h) of this title."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/7/2012?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2012. Definitions","tname":"Agriculture","by":{"0":""}},{"t":"usc","label":"7 U.S.C. § 2014","url":"https://www.law.cornell.edu/uscode/text/7/2014","subs":["(c)(2)"],"stext":{"head":"§2014. Eligible households","paras":[[0,"(a) Income and other financial resources as substantial limiting factors in obtaining more nutritious diet; recipients under Social Security Act"],[0,"Participation in the supplemental nutrition assistance program shall be limited to those households whose incomes and other financial resources, held singly or in joint ownership, are determined to be a substantial limiting factor in permitting them to obtain a more nutritious diet. Notwithstanding any other provisions of this chapter except subsections (b), (d)(2), (g), and (r) of section 2015 of this title and section 2012(m)(4) of this title, households in which each member receives benefits under a State program funded under part A of title IV of the Social Security Act (42 U.S.C. 601 et seq.), supplemental security income benefits under title XVI of the Social Security Act [42 U.S.C. 1381 et seq.], or aid to the aged, blind, or disabled under title I, X, XIV, or XVI of the Social Security Act [42 U.S.C. 301 et seq., 1201 et seq., 1351 et seq., or 1381 et seq.], shall be eligible to participate in the supplemental nutrition assistance program. Except for sections 2015, 2025(e)(1), and section 2012(m)(4) of this title, households in which each member receives benefits under a State or local general assistance program that complies with standards established by the Secretary for ensuring that the program is based on income criteria comparable to or more restrictive than those under subsection (c)(2), and not limited to one-time emergency payments that cannot be provided for more than one consecutive month, shall be eligible to participate in the supplemental nutrition assistance program. Assistance under this program shall be furnished to all eligible households who make application for such participation."],[0,"(b) Eligibility standards"],[0,"Except as otherwise provided in this chapter, the Secretary shall establish uniform national standards of eligibility (other than the income standards for Alaska, Hawaii, Guam, and the Virgin Islands of the United States established in accordance with subsections (c) and (e) of this section) for participation by households in the supplemental nutrition assistance program in accordance with the provisions of this section. No plan of operation submitted by a State agency shall be approved unless the standards of eligibility meet those established by the Secretary, and no State agency shall impose any other standards of eligibility as a condition for participating in the program."],[0,"(c) Gross income standard"],[0,"The income standards of eligibility shall be adjusted each October 1 and shall provide that a household shall be ineligible to participate in the supplemental nutrition assistance program if—"],[1,"(1) the household's income (after the exclusions and deductions provided for in subsections (d) and (e)) exceeds the poverty line, as defined in section 673(2) of the Community Services Block Grant Act (42 U.S.C. 9902(2)), for the forty-eight contiguous States and the District of Columbia, Alaska, Hawaii, the Virgin Islands of the United States, and Guam, respectively; and"],[1,"(2) in the case of a household that does not include an elderly or disabled member, the household's income (after the exclusions provided for in subsection (d) but before the deductions provided for in subsection (e)) exceeds such poverty line by more than 30 per centum."],[0,"In no event shall the standards of eligibility for the Virgin Islands of the United States or Guam exceed those in the forty-eight contiguous States."],[0,"(d) Exclusions from income"],[0,"Household income for purposes of the supplemental nutrition assistance program shall include all income from whatever source excluding only—"],[1,"(1) any gain or benefit which is not in the form of money payable directly to a household (notwithstanding its conversion in whole or in part to direct payments to households pursuant to any demonstration project carried out or authorized under Federal law including demonstration projects created by the waiver of provisions of Federal law);"],[1,"(2) any income in the certification period which is received too infrequently or irregularly to be reasonably anticipated, but not in excess of $30 in a quarter, subject to modification by the Secretary in light of subsection (f);"],[1,"(3) all educational loans on which payment is deferred, grants, scholarships, fellowships, veterans' educational benefits, and the like—"],[2,"(A) awarded to a household member enrolled at a recognized institution of post-secondary education, at a school for the handicapped, in a vocational education program, or in a program that provides for completion of a secondary school diploma or obtaining the equivalent thereof;"],[2,"(B) to the extent that they do not exceed the amount used for or made available as an allowance determined by such school, institution, program, or other grantor, for tuition and mandatory fees (including the rental or purchase of any equipment, materials, and supplies related to the pursuit of the course of study involved), books, supplies, transportation, and other miscellaneous personal expenses (other than living expenses), of the student incidental to attending such school, institution, or program; and"],[2,"(C) to the extent loans include any origination fees and insurance premiums;"],[1,"(4) all loans other than educational loans on which repayment is deferred;"],[1,"(5) reimbursements which do not exceed expenses actually incurred and which do not represent a gain or benefit to the household and any allowance a State agency provides no more frequently than annually to families with children on the occasion of those children's entering or returning to school or child care for the purpose of obtaining school clothes (except that no such allowance shall be excluded if the State agency reduces monthly assistance under a State program funded under part A of title IV of the Social Security Act (42 U.S.C. 601 et seq.) in the month for which the allowance is provided): Provided, That no portion of benefits provided under title IV–A of the Social Security Act [42 U.S.C. 601 et seq.], to the extent it is attributable to an adjustment for work-related or child care expenses (except for payments or reimbursements for such expenses made under an employment, education, or training program initiated under such title after September 19, 1988), and no portion of any educational loan on which payment is deferred, grant, scholarship, fellowship, veterans' benefits, and the like that are provided for living expenses, shall be considered such reimbursement;"],[1,"(6) moneys received and used for the care and maintenance of a third-party beneficiary who is not a household member, and child support payments made by a household member to or for an individual who is not a member of the household if the household member is legally obligated to make the payments;"],[1,"(7) income earned by a child who is a member of the household, who is an elementary or secondary school student, and who is 17 years of age or younger;"],[1,"(8) moneys received in the form of nonrecurring lump-sum payments, including, but not limited to, income tax refunds, rebates, or credits, cash donations based on need that are received from one or more private nonprofit charitable organizations, but not in excess of $300 in the aggregate in a quarter, retroactive lump-sum social security or railroad retirement pension payments and retroactive lump-sum insurance settlements: Provided, That such payments shall be counted as resources, unless specifically excluded by other laws;"],[1,"(9) the cost of producing self-employed income, but household income that otherwise is included under this subsection shall be reduced by the extent that the cost of producing self-employment income exceeds the income derived from self-employment as a farmer;"],[1,"(10) any income that any other Federal law specifically excludes from consideration as income for purposes of determining eligibility for the supplemental nutrition assistance program except as otherwise provided in subsection (k) of this section;"],[1,"(11)(A) any payments or allowances made for the purpose of providing energy assistance under any Federal law (other than part A of title IV of the Social Security Act (42 U.S.C. 601 et seq.)); or"],[1,"(B) a 1-time payment or allowance made under a Federal or State law for the costs of weatherization or emergency repair or replacement of an unsafe or inoperative furnace or other heating or cooling device;"],[1,"(12) through September 30 of any fiscal year, any increase in income attributable to a cost-of-living adjustment made on or after July 1 of such fiscal year under title II or XVI of the Social Security Act [42 U.S.C. 401 et seq., 1381 et seq.], section 3(a)(1) of the Railroad Retirement Act of 1974 (45 U.S.C. 231b(a)(1)), or section 5312 of title 38, if the household was certified as eligible to participate in the supplemental nutrition assistance program or received an allotment in the month immediately preceding the first month in which the adjustment was effective;"],[1,"(13) any payment made to the household under section 3507 1 of title 26 (relating to advance payment of earned income credit);"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/7/2014?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2014. Eligible households","tname":"Agriculture","by":{"0":""}}]};